def total(values, index=0):
    if index == len(values):
        return 0
    return values[index] + total(values, index + 1)

print(total([2, 3, 4]))

def fib(n, memo):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

print(fib(6, {}))

